// Lane D: D4 ridge tracking + robust straight-pass fit vs the Python reference (fixtures/golden_js/fit_scenarios.json,
// generated by fixtures/golden_js/make_golden_js.py from ref/doppler_ref/fit.py).
import test from 'node:test';
import assert from 'node:assert/strict';
import { loadScenario, readJson } from './geoloc_helpers.mjs';
import { trackRidgeRef, fitStraight, eventFromFit } from '../engine/geoloc/fit.js';

const G = readJson('fixtures/golden_js/fit_scenarios.json');

for (const name of ['scenario1', 'scenario2']) {
  test(`D4 ${name}: ridge points + weighted LSQ fit (F0, v, d, t_c, sigma) vs fit.py`, () => {
    const sc = loadScenario(name);
    G[name].forEach((g, e) => {
      const r = trackRidgeRef(sc.Z, sc.spec, g.seed.t, g.seed.F0);
      assert.equal(r.t.length, g.ridge.t.length, 'ridge length');
      let ef = 0;
      r.f.forEach((f, i) => { ef = Math.max(ef, Math.abs(f - g.ridge.f[i]), Math.abs(r.t[i] - g.ridge.t[i])); });
      assert.ok(ef < 1e-6, `ridge max diff ${ef}`);
      for (const [key, w] of [['fit_weighted', g.ridge.s], ['fit_unweighted', null]]) {
        const fit = fitStraight(g.ridge.t, g.ridge.f, { weights: w });
        const py = g[key];
        const line = ['F0', 'v', 'd', 't_c'].map((k) => {
          const dz = Math.abs(fit[k] - py[k]) / py.sigma[k];
          assert.ok(dz < 0.05, `${key} ${k}: js ${fit[k]} py ${py[k]} (${dz.toFixed(3)} sigma)`);
          const ds = Math.abs(fit.sigma[k] - py.sigma[k]) / py.sigma[k];
          assert.ok(ds < 0.05, `${key} sigma ${k}: js ${fit.sigma[k]} py ${py.sigma[k]}`);
          return `${k} ${fit[k].toFixed(3)}/${py[k].toFixed(3)} (+-${fit.sigma[k].toFixed(3)}/${py.sigma[k].toFixed(3)})`;
        });
        assert.ok(Math.abs(fit.rms_hz - py.rms_hz) / py.rms_hz < 0.01);
        if (key === 'fit_weighted') {
          console.log(`  ${name} ev${e} n=${r.t.length}: ${line.join(', ')}; t_cpa ${fit.t_cpa_audio.toFixed(2)} (truth ${g.truth.t_cpa_audio.toFixed(2)})`);
          const ev = eventFromFit(fit);
          assert.ok(Math.abs(ev.t_cpa_audio - g.event.t_cpa_audio) < 0.05);
        }
      }
    });
  });
}

import { fitEvent } from '../engine/geoloc.js';

test('D4 honest fitEvent: synthetic passes well constrained and truth inside the suggested ranges', async () => {
  for (const [name, evs] of Object.entries(G)) for (const [i, g] of evs.entries()) {
    const f = await fitEvent(g.ridge.t.map((t, k) => [t, g.ridge.f[k]]), { cls: 'prop' });
    const tr = g.truth;
    console.log(`  ${name} ev${i}: v ${f.point.v.toFixed(1)} [${f.v_mps.map((x) => x.toFixed(0))}] (truth ${tr.v_mps.toFixed(1)}), d ${f.point.d.toFixed(0)} [${f.cpa_m.map((x) => x.toFixed(0))}] (truth ${tr.cpa_m.toFixed(0)}), t_cpa ${f.t_cpa_audio.toFixed(1)} +- ${f.t_sigma_s.toFixed(1)} (truth ${tr.t_cpa_audio.toFixed(1)}), coverage ${f.quality.coverage.toFixed(2)}, poorly ${f.poorly_constrained}`);
    assert.ok(tr.v_mps >= f.v_mps[0] && tr.v_mps <= f.v_mps[1], 'v range');
    assert.ok(tr.cpa_m >= f.cpa_m[0] && tr.cpa_m <= f.cpa_m[1], 'd range');
    assert.ok(Math.abs(f.t_cpa_audio - tr.t_cpa_audio) <= 2 * f.t_sigma_s, 't_cpa within 2 sigma');
    assert.equal(f.poorly_constrained, false);
  }
});

test('D4 honest fitEvent: real colsto partial ridges are flagged poorly constrained with wide ranges', async () => {
  const R = readJson('fixtures/real/colsto_longisland/ridges.json');
  for (const rd of R) {
    const f = await fitEvent(rd.points.map(([t, fr]) => [t, fr / rd.harmonic]), { cls: 'prop' });
    console.log(`  colsto ev${rd.event} h${rd.harmonic}: free v ${f.unconstrained.v.toFixed(0)} d ${f.unconstrained.d.toFixed(0)} | v ${f.point.v.toFixed(0)} [${f.v_mps.map((x) => x.toFixed(0))}] d ${f.point.d.toFixed(0)} [${f.cpa_m.map((x) => x.toFixed(0))}] t_cpa ${f.t_cpa_audio.toFixed(1)} +- ${f.t_sigma_s.toFixed(1)} [${f.t_cpa_range.map((x) => x.toFixed(1))}] | ${f.quality.reasons.join('; ')}`);
    assert.equal(f.poorly_constrained, true);
    assert.ok(f.v_mps[1] / f.v_mps[0] > 1.9, 'v range honest (wide)');
    assert.ok(f.cpa_m[1] / f.cpa_m[0] > 2.5, 'd range honest (wide)');
    assert.ok(f.t_sigma_s > 3, 't_cpa uncertainty honest');
  }
});
